[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Fitness Tracker User Health &amp; Activity Analytics Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1e40af;
    --primary-light: #3b82f6;
    --primary-dark: #1e3a8a;
    --secondary: #64748b;
    --accent: #0ea5e9;
    --success: #10b981;
    --warning: #f59e0b;
    --danger: #ef4444;
    --bg: #f8fafc;
    --card-bg: #ffffff;
    --border: #e2e8f0;
    --text: #0f172a;
    --text-muted: #64748b;
    --text-light: #94a3b8;
    --font: 'Segoe UI', system-ui, -apple-system, sans-serif;
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: var(--font);
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    font-size: 14px;
  }

  /* Cover Page */
  .cover {
    background: linear-gradient(135deg, #1e3a8a 0%, #1e40af 40%, #2563eb 70%, #0ea5e9 100%);
    color: white;
    padding: 80px 60px;
    min-height: 340px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    position: relative;
    overflow: hidden;
  }
  .cover::before {
    content: '';
    position: absolute;
    top: -80px; right: -80px;
    width: 400px; height: 400px;
    background: rgba(255,255,255,0.04);
    border-radius: 50%;
  }
  .cover::after {
    content: '';
    position: absolute;
    bottom: -60px; left: -40px;
    width: 300px; height: 300px;
    background: rgba(255,255,255,0.04);
    border-radius: 50%;
  }
  .cover-badge {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    opacity: 0.7;
    margin-bottom: 16px;
  }
  .cover h1 {
    font-size: 32px;
    font-weight: 800;
    line-height: 1.2;
    margin-bottom: 12px;
    max-width: 700px;
  }
  .cover p {
    font-size: 15px;
    opacity: 0.85;
    max-width: 600px;
    margin-bottom: 32px;
  }
  .cover-meta {
    display: flex;
    gap: 32px;
    font-size: 12px;
    opacity: 0.7;
  }
  .cover-meta span { display: flex; align-items: center; gap: 6px; }

  /* Layout */
  .container { max-width: 1140px; margin: 0 auto; padding: 0 32px; }

  /* TOC */
  .toc {
    background: white;
    border-bottom: 1px solid var(--border);
    padding: 24px 0;
  }
  .toc-inner { max-width: 1140px; margin: 0 auto; padding: 0 32px; }
  .toc h2 { font-size: 13px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--text-muted); margin-bottom: 12px; }
  .toc-list { display: flex; flex-wrap: wrap; gap: 8px; list-style: none; }
  .toc-list li a {
    font-size: 12px;
    padding: 4px 12px;
    border-radius: 20px;
    border: 1px solid var(--border);
    color: var(--text-muted);
    text-decoration: none;
    transition: all 0.15s;
  }
  .toc-list li a:hover { background: var(--primary); color: white; border-color: var(--primary); }

  /* KPI Bar */
  .kpi-bar {
    background: white;
    border-bottom: 2px solid var(--border);
    padding: 20px 0;
  }
  .kpi-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 0; }
  .kpi-item {
    padding: 12px 20px;
    border-right: 1px solid var(--border);
    text-align: center;
  }
  .kpi-item:last-child { border-right: none; }
  .kpi-label { font-size: 10px; font-weight: 600; letter-spacing: 1px; text-transform: uppercase; color: var(--text-muted); margin-bottom: 4px; }
  .kpi-value { font-size: 24px; font-weight: 800; color: var(--primary-dark); line-height: 1; }
  .kpi-sub { font-size: 11px; color: var(--text-light); margin-top: 2px; }

  /* Main content */
  main { padding: 40px 0; }

  /* Section */
  .section {
    background: white;
    border-radius: 12px;
    border: 1px solid var(--border);
    margin-bottom: 32px;
    overflow: hidden;
  }
  .section-header {
    padding: 20px 28px 16px;
    border-bottom: 1px solid var(--border);
    display: flex;
    align-items: flex-start;
    gap: 16px;
  }
  .section-num {
    width: 32px; height: 32px;
    background: var(--primary);
    color: white;
    border-radius: 8px;
    display: flex; align-items: center; justify-content: center;
    font-size: 13px; font-weight: 700;
    flex-shrink: 0;
    margin-top: 2px;
  }
  .section-title { font-size: 18px; font-weight: 700; color: var(--text); margin-bottom: 2px; }
  .section-subtitle { font-size: 12px; color: var(--text-muted); }
  .section-body { padding: 24px 28px; }

  /* Chart grid */
  .chart-grid { display: grid; gap: 24px; }
  .chart-grid-2 { grid-template-columns: 1fr 1fr; }
  .chart-grid-3 { grid-template-columns: 1fr 1fr 1fr; }
  .chart-box {
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 16px;
  }
  .chart-box h4 {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.5px;
    color: var(--text-muted);
    text-transform: uppercase;
    margin-bottom: 12px;
  }
  .chart-box canvas { max-height: 260px; }

  /* Stat row */
  .stat-row {
    display: grid;
    gap: 12px;
    margin-bottom: 20px;
  }
  .stat-row-3 { grid-template-columns: repeat(3, 1fr); }
  .stat-row-4 { grid-template-columns: repeat(4, 1fr); }
  .stat-row-5 { grid-template-columns: repeat(5, 1fr); }

  .stat-card {
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 14px 16px;
    text-align: center;
  }
  .stat-card .val { font-size: 22px; font-weight: 800; color: var(--primary-dark); }
  .stat-card .lbl { font-size: 10px; font-weight: 600; letter-spacing: 0.8px; text-transform: uppercase; color: var(--text-muted); margin-top: 2px; }
  .stat-card .sub { font-size: 11px; color: var(--text-light); margin-top: 1px; }

  /* Data table */
  .data-table { width: 100%; border-collapse: collapse; font-size: 13px; }
  .data-table th {
    background: #f1f5f9;
    text-align: left;
    padding: 8px 12px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: var(--text-muted);
    border-bottom: 1px solid var(--border);
  }
  .data-table td {
    padding: 8px 12px;
    border-bottom: 1px solid #f1f5f9;
    color: var(--text);
  }
  .data-table tr:last-child td { border-bottom: none; }
  .data-table tr:hover td { background: #f8fafc; }

  /* Progress bar */
  .prog-bar-wrap { margin-bottom: 10px; }
  .prog-bar-label { display: flex; justify-content: space-between; margin-bottom: 4px; font-size: 12px; color: var(--text); }
  .prog-bar-track { height: 8px; background: var(--border); border-radius: 4px; overflow: hidden; }
  .prog-bar-fill { height: 100%; border-radius: 4px; background: linear-gradient(90deg, var(--primary-light), var(--accent)); }

  /* Callout boxes */
  .callout {
    border-radius: 8px;
    padding: 14px 18px;
    margin-bottom: 16px;
    display: flex;
    gap: 12px;
    align-items: flex-start;
    font-size: 13px;
  }
  .callout-info { background: #eff6ff; border-left: 4px solid #3b82f6; }
  .callout-success { background: #f0fdf4; border-left: 4px solid #10b981; }
  .callout-warning { background: #fffbeb; border-left: 4px solid #f59e0b; }
  .callout-danger { background: #fef2f2; border-left: 4px solid #ef4444; }
  .callout-icon { font-size: 16px; flex-shrink: 0; }
  .callout-text strong { display: block; font-size: 12px; letter-spacing: 0.5px; text-transform: uppercase; margin-bottom: 2px; }

  /* Insight cards */
  .insight-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 20px; }
  .insight-card {
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 18px;
  }
  .insight-card .ic-num {
    width: 28px; height: 28px;
    background: var(--primary);
    color: white;
    border-radius: 6px;
    font-size: 12px; font-weight: 700;
    display: flex; align-items: center; justify-content: center;
    margin-bottom: 10px;
  }
  .insight-card h4 { font-size: 14px; font-weight: 700; margin-bottom: 6px; color: var(--text); }
  .insight-card p { font-size: 12px; color: var(--text-muted); line-height: 1.5; }
  .insight-card .rec {
    margin-top: 10px;
    padding: 8px 10px;
    background: #eff6ff;
    border-radius: 6px;
    font-size: 12px;
    color: var(--primary-dark);
    font-weight: 500;
  }

  /* Horizontal bar chart (CSS) */
  .hbar-list { list-style: none; }
  .hbar-item { margin-bottom: 8px; }
  .hbar-name { font-size: 12px; margin-bottom: 3px; display: flex; justify-content: space-between; }
  .hbar-track { height: 12px; background: var(--border); border-radius: 3px; overflow: hidden; }
  .hbar-fill { height: 100%; border-radius: 3px; }

  /* Divider */
  .divider { height: 1px; background: var(--border); margin: 20px 0; }

  /* Typography */
  p { margin-bottom: 10px; color: var(--text); font-size: 13px; }
  p:last-child { margin-bottom: 0; }
  h3 { font-size: 14px; font-weight: 700; color: var(--text); margin-bottom: 10px; }

  /* Footer */
  footer {
    border-top: 1px solid var(--border);
    background: white;
    padding: 20px 0;
    text-align: center;
    font-size: 11px;
    color: var(--text-light);
  }

  /* Highlight number */
  .hl { color: var(--primary); font-weight: 700; }

  /* Tag/badge */
  .badge {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 12px;
    font-size: 11px;
    font-weight: 600;
  }
  .badge-blue { background: #dbeafe; color: #1e40af; }
  .badge-green { background: #d1fae5; color: #065f46; }
  .badge-amber { background: #fef3c7; color: #92400e; }
  .badge-red { background: #fee2e2; color: #991b1b; }

  /* Priority label */
  .priority-banner {
    background: linear-gradient(90deg, #1e3a8a, #2563eb);
    color: white;
    padding: 10px 28px;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.5px;
    border-bottom: none;
  }
  .priority-banner span { opacity: 0.7; }

  @media (max-width: 768px) {
    .chart-grid-2 { grid-template-columns: 1fr; }
    .chart-grid-3 { grid-template-columns: 1fr; }
    .kpi-grid { grid-template-columns: repeat(3, 1fr); }
    .stat-row-4 { grid-template-columns: repeat(2, 1fr); }
    .insight-grid { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>

<!-- ===== COVER ===== -->
<div class="cover">
  <div class="cover-badge">Health Analytics Team &nbsp;|&nbsp; Internal Report</div>
  <h1>Fitness Tracker User Health &amp; Activity Analytics Report</h1>
  <p>A comprehensive analysis of daily health metrics, activity patterns, and lifestyle indicators across a synthetic cohort of fitness tracker users — 2015 to 2025.</p>
  <div class="cover-meta">
    <span>&#128197; April 21, 2026</span>
    <span>&#128202; 4,000 daily records</span>
    <span>&#128337; 2015–2025 cohort</span>
    <span>&#128203; 6 analysis sections</span>
  </div>
</div>

<!-- ===== TOC ===== -->
<div class="toc">
  <div class="toc-inner">
    <h2>Sections</h2>
    <ul class="toc-list">
      <li><a href="#s0">Global KPIs</a></li>
      <li><a href="#s1">1. User Demographics</a></li>
      <li><a href="#s2">2. Physical Activity &amp; Workouts</a></li>
      <li><a href="#s3">3. Heart Rate, Sleep &amp; Calories</a></li>
      <li><a href="#s4">4. Lifestyle &amp; Wellness</a></li>
      <li><a href="#s5">&#9733; 5. Temporal Trends &amp; Seasonality</a></li>
      <li><a href="#s6">6. Key Insights &amp; Recommendations</a></li>
    </ul>
  </div>
</div>

<!-- ===== KPI BAR ===== -->
<div class="kpi-bar" id="s0">
  <div class="container">
    <div class="kpi-grid">
      <div class="kpi-item">
        <div class="kpi-label">Avg Daily Steps</div>
        <div class="kpi-value">10,574</div>
        <div class="kpi-sub">steps / day</div>
      </div>
      <div class="kpi-item">
        <div class="kpi-label">Avg Calories Burned</div>
        <div class="kpi-value">616.7</div>
        <div class="kpi-sub">kcal / day</div>
      </div>
      <div class="kpi-item">
        <div class="kpi-label">Avg Sleep Duration</div>
        <div class="kpi-value">6.99</div>
        <div class="kpi-sub">hours / night</div>
      </div>
      <div class="kpi-item">
        <div class="kpi-label">Workout Participation</div>
        <div class="kpi-value">100%</div>
        <div class="kpi-sub">all records active</div>
      </div>
      <div class="kpi-item">
        <div class="kpi-label">Avg Stress Level</div>
        <div class="kpi-value">5.45</div>
        <div class="kpi-sub">scale 1–10</div>
      </div>
    </div>
  </div>
</div>

<!-- ===== MAIN ===== -->
<main>
<div class="container">

  <!-- ===================== SECTION 1: DEMOGRAPHICS ===================== -->
  <div class="section" id="s1">
    <div class="section-header">
      <div class="section-num">1</div>
      <div>
        <div class="section-title">User Demographics &amp; Body Metrics Overview</div>
        <div class="section-subtitle">Distribution of users by age, gender, height, weight, and BMI</div>
      </div>
    </div>
    <div class="section-body">

      <div class="stat-row stat-row-4" style="margin-bottom:24px;">
        <div class="stat-card">
          <div class="val">4,000</div>
          <div class="lbl">Total Records</div>
          <div class="sub">Jan 2015 – Dec 2025</div>
        </div>
        <div class="stat-card">
          <div class="val">38.5 yrs</div>
          <div class="lbl">Mean Age</div>
          <div class="sub">Range: 18–59</div>
        </div>
        <div class="stat-card">
          <div class="val">24.6</div>
          <div class="lbl">Avg BMI</div>
          <div class="sub">Normal range</div>
        </div>
        <div class="stat-card">
          <div class="val">50.6% M</div>
          <div class="lbl">Gender Split</div>
          <div class="sub">2,025 M / 1,975 F</div>
        </div>
      </div>

      <div class="chart-grid chart-grid-2">
        <div class="chart-box">
          <h4>Gender Distribution</h4>
          <canvas id="chart-gender" height="220"></canvas>
        </div>
        <div class="chart-box">
          <h4>Age Group Distribution</h4>
          <canvas id="chart-age" height="220"></canvas>
        </div>
      </div>

      <div class="divider"></div>

      <h3>Body Metrics by Gender</h3>
      <table class="data-table">
        <thead>
          <tr>
            <th>Gender</th>
            <th>Count</th>
            <th>Avg Height (cm)</th>
            <th>Avg Weight (kg)</th>
            <th>Avg BMI</th>
            <th>Avg Steps</th>
            <th>Avg Calories</th>
          </tr>
        </thead>
        <tbody>
          <tr><td>Female</td><td>1,975</td><td>170.0</td><td>70.3</td><td>24.6</td><td>10,580</td><td>617.3</td></tr>
          <tr><td>Male</td><td>2,025</td><td>169.9</td><td>70.3</td><td>24.6</td><td>10,568</td><td>616.2</td></tr>
        </tbody>
      </table>

      <div class="divider"></div>
      <h3>Age Group Performance Summary</h3>
      <table class="data-table">
        <thead>
          <tr><th>Age Group</th><th>Avg Steps</th><th>Avg Calories</th><th>Avg Stress</th><th>Avg Workout (min)</th></tr>
        </thead>
        <tbody>
          <tr><td><span class="badge badge-blue">18–25</span></td><td>10,844</td><td>628.3</td><td>5.4</td><td>44.9</td></tr>
